const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY="ascendia_v5";
const OLD_KEY="ascendia_v4";
const defaults={profile:null,completed:[],evidence:[],scenarios:[],seenChallenges:[],lastDaily:"",dailyId:"",score:0,skills:{Social:0,Speaking:0,Assertiveness:0,Boundaries:0,"Self-trust":0,Rejection:0,Work:0},expected:[],actual:[],confidenceLogs:{},journal:[],speech:{topic:"",category:"",phase:"research",remaining:300,running:false,completed:0},appStartedAt:"",lastVisit:"",streak:0,unlockedAchievements:[]};
function load(){try{const raw=localStorage.getItem(KEY)||localStorage.getItem(OLD_KEY)||localStorage.getItem("ascendia_v3"); return {...defaults,...(raw?JSON.parse(raw):{})}}catch{return {...defaults}}}
let state=load(); state.skills={...defaults.skills,...(state.skills||{})}; state.confidenceLogs=state.confidenceLogs||{}; state.speech={...defaults.speech,...(state.speech||{})}; state.journal=state.journal||[]; state.evidence=state.evidence||[]; state.scenarios=state.scenarios||[]; state.completed=state.completed||[]; state.unlockedAchievements=state.unlockedAchievements||[]; function dateOnly(d){return new Date(d+"T12:00:00")} function addDaysKey(k,n){let d=dateOnly(k);d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`} function daysBetween(a,b){return Math.round((dateOnly(b)-dateOnly(a))/86400000)} function ensureStartDate(){const today=todayKey(),y=String(new Date().getFullYear()),logs=Object.keys(state.confidenceLogs||{}).filter(d=>d.startsWith(y)).sort();if(!/^\d{4}-\d{2}-\d{2}$/.test(state.appStartedAt||'')||!String(state.appStartedAt).startsWith(y)||state.appStartedAt>today)state.appStartedAt=logs[0]||today} ensureStartDate(); function updateStreak(){let today=todayKey();if(state.lastVisit!==today){if(state.lastVisit===addDaysKey(today,-1))state.streak=Math.max(1,(state.streak||0)+1);else state.streak=1;state.lastVisit=today;save()}} updateStreak(); save();
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function todayKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[m]))}
function toast(t){let e=$("#toast");e.textContent=t;e.classList.add("show");setTimeout(()=>e.classList.remove("show"),2300)}
let audioCtx=null;
function sound(type="click"){try{audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==="suspended")audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type==="success"?"sine":"triangle";o.frequency.value=type==="success"?660:type==="choice"?420:300;g.gain.setValueAtTime(.0001,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(type==="success"?.06:.025,audioCtx.currentTime+.01);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+(type==="success"?.18:.08));o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.2)}catch(e){}}
document.addEventListener("pointerdown",e=>{if(e.target.closest("button,.feature-card,.nav-item,.choice-btn,.legend-item,.mood-buttons button"))sound(e.target.closest(".choice-btn")?"choice":"click")},{passive:true});
function showPage(id){$$('.page').forEach(p=>p.classList.toggle('active-page',p.id===id));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===id));$("#sidebar").classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});({home:renderHome,practice:()=>renderScenarios(),challenges:renderDaily,journal:renderJournal,speech:renderSpeech,tracker:renderTracker,progress:renderProgress,evidence:renderEvidence,about:renderProfile,tips:renderTips}[id]||(()=>{}))()}
$$('[data-page]').forEach(el=>el.addEventListener('click',()=>showPage(el.dataset.page)));$("#mobileMenu").addEventListener('click',()=>$("#sidebar").classList.toggle('open'));
$("#today").textContent=new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date());
function dailyChallenge(){const key=todayKey();if(state.lastDaily===key&&state.dailyId)return CHALLENGES.find(c=>c.id===state.dailyId)||CHALLENGES[0];let used=new Set(state.seenChallenges||[]),available=CHALLENGES.filter(c=>!used.has(c.id));if(!available.length){state.seenChallenges=[];available=[...CHALLENGES]}let c=available[hash(key+'-ascendia')%available.length];state.dailyId=c.id;state.lastDaily=key;state.seenChallenges=[...(state.seenChallenges||[]),c.id];save();return c}
function renderHome(){let p=state.profile||{name:'Brave human'};$("#greeting").textContent=`HEY, ${(p.name||'BRAVE HUMAN').toUpperCase()} 👋`;let sv=$("#homeStreak");if(sv)sv.textContent=state.streak||1;$("#welcomeTitle").innerHTML=`Welcome back, ${escapeHtml(p.name||'brave human')}!<br><em>Let's practise a little bravery.</em>`;let c=dailyChallenge();$("#dailyTitle").textContent=c.title;$("#dailyDescription").textContent='One small action, chosen just for today. You do not have to feel ready before you begin.';$("#dailyDifficulty").textContent=`Level ${c.level} · ${c.category}`;$("#dailyTime").textContent=c.level===3?'10–20 min':'5–10 min';let score=Math.round(state.score||0);$("#homeScore").textContent=score;$("#homeScoreRing").style.setProperty('--score',`${score}%`);$("#scoreCaption").textContent=score===0?'Your first brave step starts here.':score<25?'Tiny steps are becoming a pattern.':score<60?'You are building momentum!':'Look at that courage glow! ✨';["Social","Speaking","Assertiveness"].forEach(k=>$("#bar"+k).style.width=Math.min(100,state.skills[k]||0)+'%')}
$("#startDaily").addEventListener('click',()=>showPage('challenges'));
const CUSTOM_SCENARIOS=Array.isArray(window.ASCENDIA_CUSTOM_SCENARIOS)?window.ASCENDIA_CUSTOM_SCENARIOS:[];const ALL_SCENARIOS=[...SCENARIOS,...CUSTOM_SCENARIOS];const SCENE_IMAGES={boundaries:'assets/scenes/angry.svg',work:'assets/scenes/work.svg',social:'assets/scenes/social.svg',speaking:'assets/scenes/speaking.svg',rejection:'assets/scenes/rejection.svg','self-trust':'assets/scenes/selftrust.svg',assertiveness:'assets/scenes/boundary.svg'};function sceneImage(s){return SCENE_IMAGES[s.category]||SCENE_IMAGES.social}
function renderScenarios(cat='all'){let list=cat==='all'?ALL_SCENARIOS:ALL_SCENARIOS.filter(s=>s.category===cat);$("#scenarioList").innerHTML=list.map(s=>`<article class="scenario-card" data-id="${escapeHtml(s.id)}"><div class="scene-art ${escapeHtml(s.category)}"><img src="${sceneImage(s)}" alt="${escapeHtml(s.title)} illustration" loading="lazy"></div><div class="scenario-copy"><span class="tag">${escapeHtml(s.category)}</span><h3>${escapeHtml(s.title)}</h3><p>${escapeHtml(s.intro)}</p><small>✦ ${Object.keys(s.nodes||{}).length} story moments</small></div></article>`).join('');$$('.scenario-card').forEach(c=>c.onclick=()=>playScenario(c.dataset.id))}
$("#practiceFilters").addEventListener('click',e=>{if(!e.target.classList.contains('filter'))return;$$('.filter').forEach(x=>x.classList.remove('active'));e.target.classList.add('active');renderScenarios(e.target.dataset.category)});
function playScenario(id){let s=ALL_SCENARIOS.find(x=>x.id===id),player=$("#scenarioPlayer");if(!s)return;$("#scenarioList").classList.add('hidden');player.classList.remove('hidden');let visited=0;function draw(n){let node=s.nodes[n],end=!!node.end;visited++;player.innerHTML=`<div class="story-top"><div><span class="tag">${s.emoji} ${escapeHtml(s.category)}</span><h2>${escapeHtml(s.title)}</h2></div><button class="secondary-btn" id="closeStory">← Back</button></div><div class="story-visual"><div class="scene-art ${escapeHtml(s.category)}"><img src="${sceneImage(s)}" alt="${escapeHtml(s.title)} illustration" loading="lazy"></div><div><small>STORY MOMENT ${visited}</small><p class="story-text">${escapeHtml(node.text||node.end||'')}</p></div></div>${end?`<div class="outcome"><strong>🌱 Your takeaway</strong><br>${escapeHtml(node.end)}</div><div class="story-actions"><button class="primary-btn" id="again">Try another path ↻</button><button class="secondary-btn" id="finishStory">Finish scenario</button></div>`:`<div class="choice-grid">${(node.choices||[]).map((c,i)=>`<button class="choice-btn" data-next="${escapeHtml(c[1])}"><span>${i+1}</span><img src="${sceneImage(s)}" alt="" loading="lazy">${escapeHtml(c[0])}</button>`).join('')}</div>`}`;$("#closeStory").onclick=()=>{player.classList.add('hidden');$("#scenarioList").classList.remove('hidden')};$$('.choice-btn').forEach(b=>b.onclick=()=>{state.scenarios.push({id,date:todayKey()});state.score=Math.min(100,(state.score||0)+.18);save();draw(b.dataset.next)});if(end){$("#again").onclick=()=>{visited=0;draw(s.start)};$("#finishStory").onclick=()=>{toast('Scenario complete. You practised a brave choice. ✨');showPage('progress');renderProgress();checkAchievements();sound('success')}}}draw(s.start)}
const JOURNAL_PROMPTS=["How confident did you feel today — and what made you feel that way?","Where did you make yourself smaller today, if anywhere?","What is one thing you handled better than you expected?","What conversation are you proud you had?","What did you want to say but hold back?","What would you tell a friend who felt exactly how you felt today?","What tiny brave action could make tomorrow 1% different?","When did you notice yourself overthinking? What happened when you kept going?","What compliment could you give yourself without adding a ‘but’?","What did you do today that future-you might thank you for?","Where did you choose yourself today?","What would you do if you knew nobody would judge you?","What did you learn about your own voice today?","What boundary would make your week easier?","When did you recover quickly after feeling embarrassed?","What are you proud of that nobody else saw?","What is one opinion you are learning to express?","What did you say yes to that you genuinely wanted?","What did you say no to that protected your peace?","What is one small promise you can keep to yourself tomorrow?","How did your body feel when you were confident today?","What fear became smaller after you acted?","What compliment was hard to receive — and why?","What would ‘taking up space’ look like tomorrow?","Where did you compare yourself, and what could you focus on instead?","What is something you can ask for instead of hoping someone notices?","What would a confident version of you say in the situation you are avoiding?","What did you do before you felt ready?","What is one mistake you survived and learned from?","Who makes you feel safe enough to be yourself?","What part of your personality deserves more room?","What would you attempt if rejection were not embarrassing?","What is one conversation you want to have more directly?","What does confidence mean to you beyond appearance?","What is one thing you know you are capable of?","Where can you replace an apology with a simple thank you?","What is one skill you want to practise instead of judging yourself for not mastering it?","What would you tell your younger self about being seen?","What is one thing you can celebrate without minimising it?","Where can you slow down instead of rushing to prove yourself?","What would you do differently if you trusted your first instinct a little more?","What kind of person do you want to be under pressure?","What is one brave question you could ask this week?","What is one thing you are no longer willing to tolerate?","What did today teach you about your limits?","What made you laugh or relax today?","What does being comfortable in your own skin look like this month?","What is one tiny experiment in confidence you could try tomorrow?","What would happen if you stopped trying to impress and started trying to connect?"];
function renderDaily(){let c=dailyChallenge(),done=state.completed.includes(c.id);$("#singleDaily").innerHTML=`<article class="daily-focus"><div class="daily-orb">${c.level===3?'🔥':'✨'}</div><span class="sticker">TODAY ONLY</span><h2>${escapeHtml(c.title)}</h2><p>This is your one assigned challenge for today. You do not need to complete every challenge in the app — just this one.</p><div class="challenge-meta"><span>Level ${c.level} · ${escapeHtml(c.category)}</span><span>${c.level===3?'10–20':'5–10'} min</span></div>${done?'<div class="done">✓ You completed today’s dare. Come back tomorrow for another.</div>':`<button class="primary-btn" id="completeDaily">I did it! Add it to my growth →</button><div class="reflection hidden" id="reflection"><label>How difficult did you expect it to be? <input id="expected" type="range" min="1" max="10" value="5"></label><label>How difficult was it in reality? <input id="actual" type="range" min="1" max="10" value="5"></label><button class="secondary-btn" id="saveReflection">Save my reflection</button></div>`}</article>`;let promptStart=hash(todayKey()+'-prompts')%JOURNAL_PROMPTS.length;let todaysPrompts=[0,1,2,3].map(i=>JOURNAL_PROMPTS[(promptStart+i)%JOURNAL_PROMPTS.length]);$("#dailyPrompts").innerHTML=todaysPrompts.map(p=>`<div class="prompt-card"><span>✦</span><p>${escapeHtml(p)}</p><button class="text-btn use-prompt" data-prompt="${escapeHtml(p)}">Use prompt →</button></div>`).join('');$$('.use-prompt').forEach(b=>b.onclick=()=>{let prompt=b.dataset.prompt;state.currentJournalPrompt=prompt;save();showPage('journal');requestAnimationFrame(()=>{let t=$("#journalText");if(t){t.focus();t.scrollIntoView({behavior:'smooth',block:'center'})}});sound('success')});if(!done){$("#completeDaily").onclick=()=>{$("#reflection").classList.remove('hidden');$("#completeDaily").classList.add('hidden');sound('success')};$("#saveReflection").onclick=()=>{let exp=+$("#expected").value,act=+$("#actual").value;state.expected.push(exp);state.actual.push(act);state.completed.push(c.id);state.score=Math.min(100,(state.score||0)+1);let k=c.category;if(state.skills[k]!==undefined)state.skills[k]=Math.min(100,state.skills[k]+1);save();sound('success');toast('Dare completed. Tiny brave step, logged. ✨');renderDaily();renderHome();renderProgress();checkAchievements()}}}
