function renderJournal(){state.journal=state.journal||[];$("#journalPrompt").textContent=state.currentJournalPrompt||'Write about what you noticed today.';$("#journalList").innerHTML=state.journal.length?state.journal.slice().reverse().map((e,i)=>`<article class="journal-entry"><div><span class="tag">${escapeHtml(e.date||'Today')}</span><strong>${escapeHtml(e.prompt||'Journal entry')}</strong></div><p>${escapeHtml(e.text)}</p><button class="text-btn delete-journal" data-i="${state.journal.length-1-i}">Delete</button></article>`).join(''):'<div class="empty-card">Your journal is waiting for its first page. ✍️</div>';$$('.delete-journal').forEach(b=>b.onclick=()=>{state.journal.splice(+b.dataset.i,1);save();renderJournal();toast('Entry deleted.')});$("#saveJournal").onclick=()=>{let text=$("#journalText").value.trim();if(!text){toast('Write a little first ✍️');return}state.journal.push({date:todayKey(),prompt:state.currentJournalPrompt||$("#journalPrompt").textContent,text});state.score=Math.min(100,(state.score||0)+.5);save();$("#journalText").value='';sound('success');toast('Journal entry saved. ✨');renderJournal();renderProgress();renderHome()};$("#clearJournal").onclick=()=>{$("#journalText").value='';sound('click')}}
let speechInterval=null;
function renderSpeech(){if(state.speech?.topic){$("#speechTopic").textContent=state.speech.topic;$("#speechCategory").textContent=state.speech.category||'RANDOM'}updateTimerUI()}
function generateTopic(){let t=SPEECH_TOPICS[hash(Date.now().toString())%SPEECH_TOPICS.length];state.speech={topic:t[0],category:t[1],phase:'research',remaining:300,running:false};save();renderSpeech();toast('New topic unlocked. You’ve got this. 🎙️');sound('success')}
$("#generateTopic").onclick=generateTopic;$("#newTopic").onclick=generateTopic;
function updateTimerUI(){let s=state.speech||defaults.speech;let mins=String(Math.floor(s.remaining/60)).padStart(2,'0'),secs=String(s.remaining%60).padStart(2,'0');$("#timerDisplay").textContent=`${mins}:${secs}`;$("#timerPhase").textContent=s.phase==='research'?'RESEARCH · 5 MIN':'SPEAK · 5 MIN';$("#timerBar").style.width=`${Math.max(0,Math.min(100,(300-s.remaining)/300*100))}%`;$("#startTimer").textContent=s.running?'Pause timer':'Start timer'}
function timerTick(){if(!state.speech.running)return;if(state.speech.remaining>0){state.speech.remaining--;updateTimerUI()}else if(state.speech.phase==='research'){state.speech.phase='speak';state.speech.remaining=300;sound('success');toast('Research time is up. Speak for five! 🎙️');updateTimerUI()}else{state.speech.running=false;state.speech.completed=(state.speech.completed||0)+1;save();sound('success');toast('Five minutes. You did it! ✨');updateTimerUI();renderProgress();checkAchievements()}}
$("#startTimer").onclick=()=>{if(!state.speech.topic){generateTopic();}state.speech.running=!state.speech.running;save();updateTimerUI();if(state.speech.running&&!speechInterval)speechInterval=setInterval(timerTick,1000)};$("#resetTimer").onclick=()=>{state.speech.running=false;state.speech.phase='research';state.speech.remaining=300;save();updateTimerUI()};
function dateRange(){const today=todayKey();let start=state.appStartedAt||today;if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||start>today)start=today;const dates=[];for(let d=dateOnly(start),end=dateOnly(today);d<=end;d.setDate(d.getDate()+1))dates.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`);return dates}
let selectedTrackerDate=todayKey();
function monthName(d){return new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(dateOnly(d))}
function renderTracker(){const dates=dateRange(),grid=$("#trackerGrid"),today=todayKey();if(!dates.includes(selectedTrackerDate))selectedTrackerDate=today;const groups={};dates.forEach(d=>(groups[d.slice(0,7)]??=[]).push(d));grid.innerHTML=Object.values(groups).map(ds=>{const offset=dateOnly(ds[0]).getDay(),blanks=Array.from({length:offset},()=>'<span class="tracker-blank"></span>').join('');return `<section class="tracker-month"><div class="tracker-month-title"><strong>${monthName(ds[0])}</strong><small>${ds.length} day${ds.length===1?'':'s'}</small></div><div class="tracker-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<span>${x}</span>`).join('')}</div><div class="tracker-days">${blanks}${ds.map(d=>{const dt=dateOnly(d),log=state.confidenceLogs[d],isToday=d===today,label=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(dt);return `<button type="button" class="tracker-cell level-${log?.level||0} ${isToday?'today-cell':''} ${selectedTrackerDate===d?'selected':''}" data-date="${d}" title="${label}"><span>${dt.getDate()}</span>${log?'<i>•</i>':''}</button>`}).join('')}</div></section>`}).join('');$("#trackerYear").textContent=new Date().getFullYear();$("#trackerMonths").innerHTML=`<span><b>Started:</b> ${new Intl.DateTimeFormat(undefined,{month:'long',day:'numeric',year:'numeric'}).format(dateOnly(state.appStartedAt))}</span><span><b>Up to:</b> ${new Intl.DateTimeFormat(undefined,{month:'long',day:'numeric',year:'numeric'}).format(new Date())}</span>`;$$('.tracker-cell').forEach(b=>b.onclick=()=>selectTrackerDate(b.dataset.date));updateTrackerSelection()}
function selectTrackerDate(d){selectedTrackerDate=d;updateTrackerSelection();let log=state.confidenceLogs[d];$("#trackerNote").value=log?.note||'';if(d===todayKey())$("#trackerPrompt").textContent='How confident do you feel today?';else $("#trackerPrompt").textContent=`How confident did you feel on ${new Intl.DateTimeFormat(undefined,{month:'long',day:'numeric',year:'numeric'}).format(dateOnly(d))}?`;$$('.mood-buttons button').forEach(x=>x.classList.toggle('chosen',x.dataset.level===String(log?.level||'')));$("#saveTracker").textContent=d===todayKey()?'Save today’s check-in ✨':`Save ${new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(dateOnly(d))} check-in ✨`;}
function updateTrackerSelection(){$$('.tracker-cell').forEach(b=>b.classList.toggle('selected',b.dataset.date===selectedTrackerDate));let log=state.confidenceLogs[selectedTrackerDate];$("#trackerSelected").innerHTML=log?`<strong>${new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(dateOnly(selectedTrackerDate))}</strong><br>${['','Low','Moderate','High','Extreme'][log.level]} confidence${log.note?' · note saved':''}`:`<strong>${new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(dateOnly(selectedTrackerDate))}</strong><br>No check-in yet`}
$$('.mood-buttons button').forEach(b=>b.onclick=()=>{$$('.mood-buttons button').forEach(x=>x.classList.remove('chosen'));b.classList.add('chosen');$("#saveTracker").dataset.level=b.dataset.level});$("#saveTracker").onclick=()=>{let level=+$("#saveTracker").dataset.level||+state.confidenceLogs[selectedTrackerDate]?.level;if(!level){toast('Pick a confidence color first 🌈');return}let wasLogged=!!state.confidenceLogs[selectedTrackerDate];state.confidenceLogs[selectedTrackerDate]={level,note:$("#trackerNote").value.trim()};if(!wasLogged)state.score=Math.min(100,(state.score||0)+.15);save();sound('success');toast(`${selectedTrackerDate===todayKey()?'Today':new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(dateOnly(selectedTrackerDate))} check-in saved. 💚`);renderTracker();selectTrackerDate(selectedTrackerDate);renderHome();renderProgress();checkAchievements()};
function getMilestones(){let actionDates=new Set([...Object.keys(state.confidenceLogs),...state.journal.map(x=>x.date),...state.evidence.map(x=>x.date),...state.scenarios.map(x=>x.date),...state.completed.map(x=>x.date)].filter(Boolean));let braveMoves=state.completed.length+state.scenarios.length+state.evidence.length;let score=Math.round(state.score||0);return [['First Step','🌱 Complete your first brave action.',state.completed.length>=1||state.scenarios.length>=1||state.evidence.length>=1],['Curious One','🔎 Practise your first scenario.',state.scenarios.length>=1],['Daredevil','🔥 Complete 3 Daily Dares.',state.completed.length>=3],['Braver Every Day','⚡ Complete 7 Daily Dares.',state.completed.length>=7],['Dare Collector','🎯 Complete 15 Daily Dares.',state.completed.length>=15],['Story Explorer','📖 Practise 5 scenarios.',state.scenarios.length>=5],['Plot Twister','🎭 Practise 15 scenario moments.',state.scenarios.length>=15],['Story Weaver','🧵 Practise 30 scenario moments.',state.scenarios.length>=30],['Find Your Voice','🎙️ Complete an Impromptu Lab session.',state.speech.completed>=1],['Mic On','📣 Complete 5 Impromptu Lab sessions.',state.speech.completed>=5],['Stage Ready','🎤 Complete 10 Impromptu Lab sessions.',state.speech.completed>=10],['Paper Trail','📓 Save 5 journal entries.',state.journal.length>=5],['Dear Diary','💌 Save 15 journal entries.',state.journal.length>=15],['Open Book','📖 Save 30 journal entries.',state.journal.length>=30],['Evidence Collector','📌 Save 5 brave moments.',state.evidence.length>=5],['Proof Pile','🧾 Save 15 brave moments.',state.evidence.length>=15],['Courage Museum','🏛️ Save 30 brave moments.',state.evidence.length>=30],['Colour Your Courage','🌈 Log confidence for 7 days.',Object.keys(state.confidenceLogs).length>=7],['Full Spectrum','🎨 Use all 4 confidence levels.',new Set(Object.values(state.confidenceLogs).map(x=>x.level)).size>=4],['Returner','🔄 Show up on 7 different days.',actionDates.size>=7],['Consistency Queen','👑 Show up on 30 different days.',actionDates.size>=30],['Three-Week Spark','🔥 Show up on 21 different days.',actionDates.size>=21],['30 Brave Moves','🚀 Reach 30 logged brave actions.',braveMoves>=30],['100 Brave Moves','💫 Reach 100 logged brave actions.',braveMoves>=100],['Practice Machine','⚙️ Reach 200 brave actions.',braveMoves>=200],['50 Points','✨ Reach 50 points of practice.',score>=50],['100 Points','🏆 Reach 100 points of practice.',score>=100],['Brave Writer','✍️ Save your first Journal Pad entry.',state.journal.length>=1],['Courage Archive','🗂️ Keep 25 total journal + evidence records.',state.journal.length+state.evidence.length>=25],['First Check-In','📅 Log your first confidence check-in.',Object.keys(state.confidenceLogs).length>=1],['Three-Day Streak','🔥 Return for 3 days in a row.',(state.streak||0)>=3],['Week Streak','🌟 Return for 7 days in a row.',(state.streak||0)>=7],['Two-Week Streak','💖 Return for 14 days in a row.',(state.streak||0)>=14],['Month Streak','👑 Return for 30 days in a row.',(state.streak||0)>=30],['Week of Courage','🗓️ Log 7 consecutive calendar days.',hasConsecutiveDays(7)],['Fortnight Flame','🔥 Log 14 consecutive calendar days.',hasConsecutiveDays(14)],['Month of Courage','🌙 Log 30 consecutive calendar days.',hasConsecutiveDays(30)],['Ascendia','🌟 Reach 200 combined practice actions.',braveMoves+state.journal.length+state.speech.completed>=200]]}
function hasConsecutiveDays(n){let ds=Object.keys(state.confidenceLogs).sort();if(ds.length<n)return false;let run=1;for(let i=1;i<ds.length;i++){run=addDaysKey(ds[i-1],1)===ds[i]?run+1:1;if(run>=n)return true}return run>=n}
function achievementPopup(name,desc){let old=$("#achievementPopup");if(old)old.remove();let e=document.createElement('div');e.id='achievementPopup';e.className='achievement-popup';e.innerHTML=`<div class="achievement-burst">🏆</div><div class="achievement-pop-label">ACHIEVEMENT UNLOCKED</div><h2>${escapeHtml(name)}</h2><p>${escapeHtml(desc)}</p><button class="primary-btn" id="closeAchievement">Keep going ✨</button>`;document.body.appendChild(e);requestAnimationFrame(()=>e.classList.add('show'));$("#closeAchievement").onclick=()=>e.remove();setTimeout(()=>{if(e.isConnected)e.remove()},6500);sound('success')}
function checkAchievements(){let milestones=getMilestones(),known=new Set(state.unlockedAchievements||[]),newOnes=[];milestones.forEach(([n,d,ok])=>{if(ok&&!known.has(n)){known.add(n);newOnes.push([n,d])}});if(newOnes.length){state.unlockedAchievements=[...known];save();achievementPopup(newOnes[0][0],newOnes[0][1]);if(newOnes.length>1)setTimeout(()=>toast(`+${newOnes.length-1} more achievement${newOnes.length>2?'s':''} unlocked! 🏆`),700)} }
function renderProgress(){let score=Math.round(state.score||0);$("#progressScore").textContent=score;$("#completedCount").textContent=state.completed.length;$("#scenarioCount").textContent=state.scenarios.length;$("#evidenceCount").textContent=state.evidence.length;$("#progressScoreText").textContent=score===0?'Your journey starts with one action.':score<25?'You are building the habit.':score<60?'Consistency is starting to show.':'You have collected meaningful evidence.';$("#skillBars").innerHTML=Object.entries(state.skills).map(([k,v])=>`<div class="skill-row"><span>${k}</span><div class="skill-track"><b class="skill-fill" style="width:${Math.min(100,v)}%"></b></div><strong>${Math.round(v)}</strong></div>`).join('');let avg=a=>a.length?(a.reduce((x,y)=>x+y,0)/a.length).toFixed(1):'—';$("#expectedAvg").textContent=avg(state.expected);$("#actualAvg").textContent=avg(state.actual);let streak=$("#streakValue");if(streak)streak.textContent=state.streak||1;let milestones=getMilestones();$("#achievementGrid").innerHTML=milestones.map(([n,d,ok])=>`<article class="achievement ${ok?'unlocked':''}"><span class="achievement-icon">${ok?'🏆':'🔒'}</span><div><strong>${escapeHtml(n)}</strong><small>${escapeHtml(d)}</small></div></article>`).join('')}
function renderEvidence(){$("#evidenceList").innerHTML=state.evidence.length?state.evidence.slice().reverse().map((e,i)=>`<article class="evidence-item"><button class="delete-evidence" data-i="${state.evidence.length-1-i}">×</button><p>“${escapeHtml(e.text)}”</p><small>${e.date||'Today'} · brave moment 💛</small></article>`).join(''):'<div class="empty-card">Your wall is empty — go collect your first receipt. 💌</div>';$$('.delete-evidence').forEach(b=>b.onclick=()=>{state.evidence.splice(+b.dataset.i,1);save();renderEvidence();renderProgress()})}
$("#evidenceDate").value=todayKey();$("#evidenceForm").addEventListener('submit',e=>{e.preventDefault();let text=$("#evidenceText").value.trim();if(!text)return;state.evidence.push({text,date:$("#evidenceDate").value||todayKey()});state.score=Math.min(100,(state.score||0)+.5);save();$("#evidenceText").value='';sound('success');toast('Your brave moment is now a sticky note! 📌');renderEvidence();renderProgress();renderHome();checkAchievements()});
function renderProfile(){let p=state.profile||{name:'',age:'',country:'',goal:'',dob:'',aspect:'social'};$("#profileSummary").textContent=`Your profile, ${p.name||'brave human'} ✨`;$("#editName").value=p.name||'';$("#editCountry").value=p.country||'';$("#editDob").value=p.dob||''}
$("#editProfileForm").addEventListener('submit',e=>{e.preventDefault();state.profile={...state.profile,name:$("#editName").value.trim(),country:$("#editCountry").value.trim(),dob:$("#editDob").value};save();sound('success');toast('Profile updated 💛');renderHome();renderProfile()});
$("#profileForm").addEventListener('submit',e=>{e.preventDefault();let aspect=$("#profileAspect").value;let goal=$("#profileGoal").value.trim();let age=$("#profileAge").value.trim();state.profile={name:$("#profileName").value.trim(),age,country:$("#profileCountry").value.trim(),goal,dob:$("#profileDob")?.value||'',aspect};save();const rec={social:{title:'Your Social Confidence path',text:'You told us you want to feel more comfortable around people. Start small and practise being seen without forcing yourself to become someone else.',features:[['Scenario Lab','Practise introductions, awkward moments, group conversations and social pressure through branching stories.','practice'],['Daily Dare','Take one small real-world social action each day.','challenges'],['Confidence Wiki','Open guides for starting conversations, speaking up and handling awkward moments.','tips'],['Brave Wall','Record the moments when you actually did the thing you were nervous about.','evidence']]},speaking:{title:'Your Speaking Confidence path',text:'Your goal is to become more comfortable using your voice. Ascendia gives you low-pressure repetition before you need to perform in public.',features:[['Impromptu Lab','Get a random topic, prepare for five minutes, then speak for five minutes.','speech'],['Speaking Scenarios','Rehearse presentations, class questions and difficult speaking moments.','practice'],['Confidence Wiki','Use speaking-up and public-speaking exercises to practise specific skills.','tips'],['Confidence Tracker','Notice how your confidence changes before and after speaking.','tracker']]},assertiveness:{title:'Your Assertiveness path',text:'You want to express yourself more clearly without becoming aggressive. Practise saying what you mean and asking for what you need.',features:[['Scenario Lab','Make decisions in situations involving pressure, disagreement and speaking up.','practice'],['Confidence Wiki','Practise direct requests, confident language and difficult messages.','tips'],['Daily Dare','Turn assertiveness into tiny real-life actions.','challenges'],['Journal Pad','Reflect on where you softened your message and what you actually wanted to say.','journal']]},boundaries:{title:'Your Boundaries path',text:'You want to protect your time, energy and comfort while still communicating with respect.',features:[['Boundary Wiki','Practise boundary situations with interactive exercises, not just reading.','tips'],['Scenario Lab','Work through realistic situations where someone pushes your limits.','practice'],['Daily Dare','Try one small boundary action in real life.','challenges'],['Journal Pad','Write down what happened and what you would like to do next time.','journal']]},'self-trust':{title:'Your Self-Trust path',text:'You want to stop second-guessing yourself and become more comfortable making decisions and taking action.',features:[['Confidence Tracker','Log your confidence day by day and look back at your patterns.','tracker'],['Journal Pad','Turn overthinking into facts, feelings and useful next steps.','journal'],['Self-Trust Wiki','Use exercises that help separate fear from facts and build small promises you can keep.','tips'],['Scenario Lab','Practise choosing instead of automatically seeking approval.','practice']]},rejection:{title:'Your Rejection Resilience path',text:'You want rejection to hurt less and stop one “no” from becoming a judgement about who you are.',features:[['Rejection Scenarios','Practise realistic rejection moments and choose how you recover.','practice'],['Journal Pad','Process what happened without turning one outcome into an identity.','journal'],['Daily Dare','Take small risks where a “no” is possible — safely and deliberately.','challenges'],['Confidence Wiki','Use the rejection and self-talk exercises to practise recovery.','tips']]},work:{title:'Your Professional Confidence path',text:'You want to communicate more confidently in work, university or professional settings.',features:[['Work Scenarios','Rehearse bosses, meetings, feedback, requests and workplace pressure.','practice'],['Confidence Wiki','Practise speaking to your boss, asking for help, negotiating and speaking up.','tips'],['Impromptu Lab','Build the ability to organise your thoughts quickly and speak clearly.','speech'],['Daily Dare','Turn practice into small professional actions.','challenges']]}}[aspect]||null;const target=rec||{title:'Your Ascendia starting path',text:`Your goal: “${goal}”`,features:[['Scenario Lab','Practise realistic situations and build confidence through decisions.','practice'],['Confidence Wiki','Explore practical guides and interactive confidence exercises.','tips'],['Daily Dare','Take one small brave action each day.','challenges'],['Journal Pad','Reflect, notice patterns and keep your progress.','journal']]};$("#onboardRecommendation").innerHTML=`<div class="onboard-rec-header"><span class="eyebrow">YOUR PERSONAL STARTING PATH</span><h2>${escapeHtml(target.title)}</h2><p>${escapeHtml(target.text)}</p><p class="goal-quote">“${escapeHtml(goal)}”</p></div><div class="rec-feature-grid">${target.features.map(([name,desc,page])=>`<button type="button" class="rec-feature" data-rec-page="${page}"><strong>${escapeHtml(name)}</strong><span>${escapeHtml(desc)}</span><b>Explore →</b></button>`).join('')}</div><button type="button" class="primary-btn" id="enterFromRecommendation">Start my Ascendia journey ✨</button>`;$("#onboardRecommendation").classList.remove('hidden');$("#profileForm button[type=submit]").classList.add('hidden');$$('.rec-feature').forEach(b=>b.onclick=()=>{state.profile.recommendedPage=b.dataset.recPage;save();$("#onboarding").classList.add('hidden');showPage(b.dataset.recPage);sound('success')});$("#enterFromRecommendation").onclick=()=>{$("#onboarding").classList.add('hidden');renderHome();sound('success');toast(`Welcome to Ascendia, ${state.profile.name}! ✨`)} });
const TIPS=[{id:'boss',title:'How to talk to your boss',icon:'💼',intro:'Be clear, calm and specific when you need feedback, support or a conversation.',steps:['Start with the point: “Can I run something by you?”','Describe the situation without over-explaining.','Say what you need: feedback, time, clarity or support.','Confirm the next step before leaving.'],say:['“I’d like your feedback on one thing.”','“Here’s what I’ve tried so far.”','“What would you like me to prioritise?”'],avoid:['“Sorry to bother you…”','“This might be stupid…”','Long explanations before the actual question.'],activity:'Rewrite one anxious message to your boss into three sentences: context → request → next step.'},{id:'confident-say',title:'Things to say to sound more confident',icon:'🗣️',intro:'Confidence often sounds like clarity rather than complicated vocabulary.',steps:['Use shorter sentences.','Replace hedging with direct language.','Pause instead of filling silence.','Finish your sentence without turning it into a question.'],say:['“I think we should try…”','“I can take that on.”','“I need more information before I decide.”','“My view is…”'],avoid:['“I’m probably wrong but…”','“Sorry, I just wanted to say…”','“Does that make sense?” after every point.'],activity:'Pick one sentence and say it out loud five times, slowly.'},{id:'boundaries',title:'How to set a boundary without being rude',icon:'🚪',intro:'A boundary explains what you will do. It does not require the other person to agree.',steps:['Name the situation.','State your limit.','Offer an alternative only if you genuinely want to.','Stop explaining once you have been clear.'],say:['“I can’t do that today.”','“I’m not comfortable with that.”','“I can help for 20 minutes, then I need to go.”'],avoid:['Threats disguised as boundaries.','Huge justifications to earn permission.','Agreeing while secretly hoping they understand your resentment.'],activity:'Write one boundary in one sentence, then remove every apology from it.'},{id:'strangers',title:'How to start a conversation with a stranger',icon:'👋',intro:'You do not need a brilliant opener. Curiosity is enough.',steps:['Use the environment.','Ask an easy question.','Listen for one detail.','Ask one follow-up.','Exit naturally if the conversation is done.'],say:['“Hey, have you been here before?”','“What brought you here?”','“How did you get into that?”'],avoid:['Interviewing them with ten questions in a row.','Trying too hard to impress.','Treating a short conversation as a failure.'],activity:'Ask one low-stakes question to someone today.'},{id:'rejection',title:'How to handle rejection',icon:'🌱',intro:'Rejection is information about one opportunity or interaction, not a complete verdict about you.',steps:['Let the first emotion exist.','Separate the outcome from your identity.','Ask what, if anything, you can learn.','Choose your next action.'],say:['“That didn’t work out, and I can handle that.”','“Is there anything useful I can learn from this?”','“What is the next opportunity?”'],avoid:['Begging for a different answer.','Turning one no into “nobody will ever choose me.”','Immediately judging yourself.'],activity:'Write down one past rejection and three things it did not prove about you.'},{id:'presentation',title:'How to speak when your voice shakes',icon:'🎙️',intro:'You can speak while nervous. The goal is control, not zero nerves.',steps:['Exhale before your first sentence.','Slow your first 10 words.','Look at one friendly face or one point above the audience.','Pause between ideas.'],say:['“There are three things I want to share.”','“Let me put that another way.”','“Give me a second to think.”'],avoid:['Rushing to escape the moment.','Apologising for being nervous.','Reading every word from a screen.'],activity:'Record a 60-second answer and watch it once without criticising your appearance.'},{id:'feedback',title:'How to receive criticism without shrinking',icon:'🪞',intro:'You can listen to feedback without agreeing with every interpretation of you.',steps:['Listen for the specific behaviour.','Ask for an example.','Decide what is useful.','Thank them for the information.'],say:['“Can you give me an example?”','“What would you like me to do differently?”','“I’ll think about that.”'],avoid:['Defending every detail instantly.','Agreeing with insults just to end the conversation.','Treating feedback as your entire identity.'],activity:'Turn one vague criticism into a specific, actionable question.'},{id:'camera',title:'How to feel more confident on camera',icon:'📹',intro:'Camera confidence is a practice loop: record, review, adjust, repeat.',steps:['Speak to one person, not “the internet.”','Use a simple three-point structure.','Record short takes.','Review one strength and one adjustment.'],say:['“Here’s the one thing I want you to know…”','“Let me show you what I mean.”'],avoid:['Watching the clip twenty times looking for flaws.','Trying to sound like another creator.','Waiting for a perfect setup.'],activity:'Record a 30-second video explaining something you already know.'},{id:'meeting',title:'How to speak up in a meeting',icon:'💡',intro:'Prepare one useful sentence before the meeting so your brain has a doorway in.',steps:['Write one point or question beforehand.','Enter with a short sentence.','Stop after the useful point.','Let other people respond.'],say:['“Can I add one thing?”','“I noticed one issue we should consider.”','“My suggestion is…”'],avoid:['Waiting until your idea is perfect.','Giving the entire backstory before your point.','Assuming silence means rejection.'],activity:'Prepare one sentence you can say in your next meeting.'},{id:'awkward',title:'What to do after an awkward moment',icon:'😅',intro:'Most awkward moments shrink when you stop trying to erase them.',steps:['Pause.','Acknowledge lightly if needed.','Continue the interaction.','Do not replay it all night.'],say:['“Well… that came out differently in my head.”','“Anyway, what I meant was…”'],avoid:['Over-apologising.','Making the moment bigger than it was.','Assuming everyone is still thinking about it.'],activity:'Tell yourself the same story you would tell a friend who made the same mistake.'},{id:'negotiation',title:'How to ask for what you want',icon:'🤝',intro:'A confident request gives the other person enough information to answer.',steps:['Say what you want.','Give the relevant reason, briefly.','Ask directly.','Allow silence.'],say:['“Would you be open to…?”','“I’m asking for…”','“What would make this workable?”'],avoid:['Hinting and hoping.','Apologising for having a reasonable request.','Answering your own request before they do.'],activity:'Turn one thing you have been hinting about into a direct request.'},{id:'people-pleasing',title:'How to stop automatically pleasing everyone',icon:'🫶',intro:'You can be kind without making every person’s comfort your responsibility.',steps:['Notice the automatic yes.','Pause before answering.','Check what you actually want or can do.','Give an honest answer.'],say:['“Let me check and get back to you.”','“I can’t commit to that.”','“I can do X, but not Y.”'],avoid:['Instant yeses followed by resentment.','Inventing excuses when a simple no would do.','Treating disappointment as proof you did something wrong.'],activity:'Delay one non-urgent answer today by 10 minutes so you can choose rather than react.'},{id:'self-talk',title:'How to talk to yourself like someone you respect',icon:'💗',intro:'Confidence grows when your inner voice stops turning every mistake into a character verdict.',steps:['Name the fact.','Name the feeling.','Choose a useful next step.'],say:['“That was difficult, and I can learn from it.”','“I made a mistake; I am not a mistake.”','“What is the next helpful action?”'],avoid:['“I always ruin everything.”','“Everyone is better than me.”','Using insults as motivation.'],activity:'Rewrite one harsh thought into a factual sentence and a next step.'}];
const EXTRA_TIPS=[{id:'ask-help',title:'How to ask for help without feeling weak',icon:'🫶',intro:'Asking clearly can show preparation, not incompetence.',steps:['Name what you are trying to solve.','Say what you already tried.','Point to the exact part where you are stuck.','Ask for the smallest useful help.'],say:['“I tried A and B; I’m stuck on C—could you point me in the right direction?”'],avoid:['“I’m useless at this.”','Making someone guess what you need.'],activity:'Build a specific help request from what you are stuck on.'},{id:'stop-comparing',title:'How to stop comparing yourself to everyone',icon:'🪞',intro:'Turn comparison into information instead of evidence against yourself.',steps:['Name what you admire specifically.','Separate their timeline from yours.','Choose one behaviour you can practise.','Return attention to your next step.'],say:['“What exactly do I admire here?”'],avoid:['“I should be where they are.”','Using someone else’s highlight reel as your baseline.'],activity:'Name one quality you admire and choose one tiny action that expresses it in your own way.'},{id:'receive-compliment',title:'How to receive a compliment',icon:'💐',intro:'You do not have to reject a kind observation to stay humble.',steps:['Pause.','Say thank you.','Let the compliment land.','Do not immediately argue with it.'],say:['“Thank you. I really appreciate that.”'],avoid:['“No, I look terrible.”','Explaining why they are wrong.'],activity:'Practise receiving one compliment today without adding a self-deprecating “but”.'},{id:'speak-up-class',title:'How to speak up in class',icon:'✋',intro:'Make participation smaller: one sentence is enough to build the habit.',steps:['Prepare one point before class.','Enter with a short opener.','Say the useful sentence.','Let the room respond.'],say:['“Can I add one point?”','“Could you clarify one part?”'],avoid:['Waiting until your thought is perfect.','Apologising before every question.'],activity:'Prepare one sentence for your next class and say it before overthinking takes over.'},{id:'difficult-text',title:'How to send a difficult message',icon:'💬',intro:'Clear messages reduce the spiral of rewriting the same sentence twenty times.',steps:['Say the point early.','Use one or two facts.','State what you need.','Stop editing once it is clear.'],say:['“I wanted to clarify something.”','“Here is what I need from you.”'],avoid:['Five paragraphs of apology.','Vague hints.'],activity:'Write a difficult message in three lines: context → request → next step.'},{id:'take-up-space',title:'How to take up space without becoming loud',icon:'🌟',intro:'Presence is often about pace, posture and allowing yourself to finish.',steps:['Plant your feet.','Speak slightly slower.','Finish the sentence.','Allow a beat of silence.'],say:['“My view is…”','“I’d like to add something.”'],avoid:['Rushing because you feel watched.','Apologising for contributing.'],activity:'Practise one 30-second answer while keeping your feet planted and allowing two pauses.'}];
const WIKI_ACTIVITIES={boss:{type:'choice',label:'🎯 CHOOSE YOUR MOVE',question:'Your boss needs something today, but you already have two urgent tasks. What do you say?',options:['“Okay, I’ll try to fit it in.”','“I can do this today, but I’ll need to move X or Y. Which should take priority?”','“Sorry, I’m already too busy.”'],correct:1,feedback:'Name the constraint and ask for a priority.'},'confident-say':{type:'choice',label:'🧩 UPGRADE THE SENTENCE',question:'Which sounds clear without sounding aggressive?',options:['“Sorry, I was just wondering if maybe…”','“Could you send that by 3 PM?”','“You need to send that now.”'],correct:1,feedback:'Clear + specific is the sweet spot.'},boundaries:{type:'multi',label:'🚪 BUILD YOUR BOUNDARY',question:'Select the three useful pieces of a healthy boundary.',options:['What I can/can’t do','A long apology','What I will do next','An insult','A genuine alternative'],correct:[0,2,4],feedback:'A useful boundary names the limit, your next action, and an optional genuine alternative.'},strangers:{type:'order',label:'🪜 CONVERSATION LADDER',question:'Tap these in the order you would naturally use them.',options:['Start with the environment','Ask one easy question','Listen for one detail','Ask one follow-up','Let the conversation breathe'],feedback:'Curiosity beats performing. Let the conversation build one step at a time.'},rejection:{type:'choice',label:'🧠 FACT OR STORY?',question:'Which thought is a fact rather than an identity verdict?',options:['“They chose someone else.”','“I am never good enough.”','“Nobody will ever want me.”'],correct:0,feedback:'One outcome is information. It is not a complete verdict about you.'},presentation:{type:'breath',label:'🌬️ STEADY YOUR VOICE',question:'Complete a 20-second reset: gentle inhale → longer exhale → relax shoulders → say your first sentence slowly.',feedback:'You are practising speaking while nervous, not waiting to become perfectly calm.'},feedback:{type:'write',label:'🔎 MAKE FEEDBACK USEFUL',question:'Turn “You need to be better” into one specific question.',placeholder:'Example: What exactly would you like me to change?',feedback:'Specific questions turn vague criticism into something actionable.'},camera:{type:'rate',label:'📹 CAMERA COURAGE CHECK',question:'Rate your behaviour, not your appearance.',items:['How clear was I?','How present did I seem?','How much did I sound like myself?'],feedback:'Keep one strength and one adjustment.'},meeting:{type:'countdown',label:'⚡ THREE-SECOND SPEAK-UP',question:'Imagine you have one useful idea in a meeting. Start within 3 seconds.',feedback:'The exercise is entering the conversation before overthinking takes over.'},awkward:{type:'choice',label:'😅 RECOVERY PICKER',question:'You accidentally call someone by the wrong name. What makes the moment smaller?',options:['Pretend nothing happened.','“Sorry—I got your name wrong. Thanks for correcting me.” Then continue.','Apologise five more times.'],correct:1,feedback:'Brief acknowledgement + moving on is enough.'},negotiation:{type:'form',label:'🤝 REQUEST BUILDER',fields:['What I want:','Why it matters briefly:','My direct question:'],feedback:'A confident request gives enough information to answer, then allows silence.'},'people-pleasing':{type:'pause',label:'⏸️ THE 10-SECOND PAUSE',question:'Before your next non-urgent favour request, pause and ask: Do I want to? Can I? What will it cost me?',feedback:'The pause creates space between a request and an automatic yes.'},'self-talk':{type:'form',label:'💗 FACT → FEELING → NEXT STEP',fields:['What actually happened?','What did I feel?','What is one useful next step?'],feedback:'Grounded self-talk separates facts, feelings and action.'},'ask-help':{type:'choice',label:'🫶 ASKING IS A SKILL',question:'You are stuck. What is the strongest move?',options:['Hide it until someone notices.','“I tried A and B. I’m stuck on C—could you point me in the right direction?”','“I’m terrible at this. Can you do it for me?”'],correct:1,feedback:'Showing what you tried makes your request specific and shows ownership.'},'stop-comparing':{type:'choice',label:'🪞 COMPARISON RESET',question:'Which response brings attention back to your own lane?',options:['“They are ahead, so I am behind.”','“What exactly do I admire, and what tiny action can I borrow?”','“I should become exactly like them.”'],correct:1,feedback:'Turn comparison into information, then choose your own version.'},'receive-compliment':{type:'micro',label:'💐 ACCEPT THE COMPLIMENT',question:'Say out loud: “Thank you. I really appreciate that.” Then stop.',feedback:'Receiving positive information without batting it away is a small confidence practice.'},'speak-up-class':{type:'countdown',label:'✋ ONE-SENTENCE CHALLENGE',question:'Prepare one sentence you can contribute in your next class. Your job is simply to say it.',feedback:'One sentence is enough to practise participation.'},'difficult-text':{type:'form',label:'💬 DIFFICULT MESSAGE BUILDER',fields:['Context:','What I need:','Next step:'],feedback:'Clear messages can be built as context → request → next step.'},'take-up-space':{type:'countdown',label:'🌟 PRESENCE PRACTICE',question:'For 30 seconds, plant your feet, slow your pace and finish every sentence.',feedback:'Presence is pace, posture and allowing yourself to finish—not volume.'}};
const ALL_TIPS=[...TIPS,...EXTRA_TIPS];
function wikiVisual(t){return `<div class="wiki-visual"><div class="wiki-visual-glow"></div><div class="wiki-visual-icon">${t.icon}</div><div class="wiki-visual-spark">✦</div><div class="wiki-visual-label">PRACTISE IT</div></div>`}
function renderTips(){const list=$("#tipList"),detail=$("#tipDetail");list.classList.remove('hidden');detail.classList.add('hidden');detail.classList.remove('wiki-modal-open');document.body.classList.remove('wiki-modal-lock');detail.classList.remove('wiki-modal-open');document.body.classList.remove('wiki-modal-lock');list.innerHTML=ALL_TIPS.map((t,i)=>`<article class="tip-card" style="--delay:${i*25}ms"><div class="tip-card-art"><span>${t.icon}</span></div><div class="tip-card-copy"><span class="tip-number">${String(i+1).padStart(2,'0')}</span><strong>${escapeHtml(t.title)}</strong><small>${escapeHtml(t.intro)}</small><button type="button" class="primary-btn explore-tip" data-tip="${escapeHtml(t.id)}">Explore guide <span>→</span></button></div></article>`).join('');$$('.explore-tip').forEach(b=>b.onclick=()=>{renderTipDetail(b.dataset.tip);sound('success')})}
function renderTipDetail(id){const t=ALL_TIPS.find(x=>x.id===id)||ALL_TIPS[0],a=WIKI_ACTIVITIES[t.id]||{type:'write',label:'🎯 TRY IT',question:t.activity,feedback:'Practise once, notice what felt difficult, then try again.'};let activity='';if(a.type==='choice')activity=`<div class="wiki-activity"><span class="activity-kicker">${a.label}</span><h3>${escapeHtml(a.question)}</h3><div class="wiki-options">${a.options.map((o,i)=>`<button class="wiki-option" data-choice="${i}">${String.fromCharCode(65+i)} · ${escapeHtml(o)}</button>`).join('')}</div><div id="wikiFeedback" class="wiki-feedback hidden"></div></div>`;else if(a.type==='multi')activity=`<div class="wiki-activity"><span class="activity-kicker">${a.label}</span><h3>${escapeHtml(a.question)}</h3><div class="wiki-checks">${a.options.map((o,i)=>`<label><input type="checkbox" data-check="${i}"><span>${escapeHtml(o)}</span></label>`).join('')}</div><button class="primary-btn" id="checkWiki">Check my boundary →</button><div id="wikiFeedback" class="wiki-feedback hidden"></div></div>`;else if(a.type==='order')activity=`<div class="wiki-activity"><span class="activity-kicker">${a.label}</span><h3>${escapeHtml(a.question)}</h3><div class="ladder-list">${a.options.map((o,i)=>`<button class="ladder-step" data-step="${i}"><b>${i+1}</b><span>${escapeHtml(o)}</span></button>`).join('')}</div><div id="wikiFeedback" class="wiki-feedback hidden"></div></div>`;else if(a.type==='breath')activity=`<div class="wiki-activity"><span class="activity-kicker">${a.label}</span><div class="breath-orb" id="breathOrb">20</div><p>${escapeHtml(a.question)}</p><button class="primary-btn" id="startBreath">Start reset</button><div id="wikiFeedback" class="wiki-feedback hidden"></div></div>`;else if(a.type==='write')activity=`<div class="wiki-activity"><span class="activity-kicker">${a.label}</span><h3>${escapeHtml(a.question)}</h3><textarea id="tipPractice" placeholder="${escapeHtml(a.placeholder||'Write your response…')}"></textarea><button class="primary-btn" id="saveTipPractice">Save practice</button><p class="wiki-reveal">${escapeHtml(a.feedback)}</p></div>`;else if(a.type==='rate')activity=`<div class="wiki-activity"><span class="activity-kicker">${a.label}</span><h3>${escapeHtml(a.question)}</h3><div class="wiki-ratings">${a.items.map(x=>`<label>${escapeHtml(x)}<input type="range" min="1" max="5" value="3"><span>3/5</span></label>`).join('')}</div><p class="wiki-reveal">${escapeHtml(a.feedback)}</p></div>`;else if(a.type==='countdown')activity=`<div class="wiki-activity"><span class="activity-kicker">${a.label}</span><h3>${escapeHtml(a.question)}</h3><div class="mini-timer" id="wikiTimer">03</div><button class="primary-btn" id="startWikiTimer">Start</button><div id="wikiFeedback" class="wiki-feedback hidden"></div></div>`;else if(a.type==='form')activity=`<div class="wiki-activity"><span class="activity-kicker">${a.label}</span><h3>Fill this out before you overthink it.</h3><div class="builder-fields">${a.fields.map(f=>`<label>${escapeHtml(f)}<textarea class="wiki-builder-field" maxlength="220"></textarea></label>`).join('')}</div><button class="primary-btn" id="saveTipPractice">Save practice →</button><p class="wiki-reveal">${escapeHtml(a.feedback)}</p></div>`;else if(a.type==='pause')activity=`<div class="wiki-activity"><span class="activity-kicker">${a.label}</span><h3>${escapeHtml(a.question)}</h3><div class="pause-count" id="pauseCount">10</div><button class="primary-btn" id="startPause">Start pause</button><p id="pausePrompt" class="wiki-reveal hidden">Now decide deliberately instead of automatically.</p></div>`;else activity=`<div class="wiki-activity micro-activity"><span class="activity-kicker">${a.label}</span><div class="compliment-card">“Thank you. I really appreciate that.”</div><button class="primary-btn" id="microDone">I said it out loud ✨</button><div id="wikiFeedback" class="wiki-feedback hidden"></div></div>`;const d=$("#tipDetail");d.classList.remove('hidden');d.classList.add('wiki-modal-open');document.body.classList.add('wiki-modal-lock');d.innerHTML=`<button class="secondary-btn wiki-back" id="wikiBack">← All guides</button><div class="tip-hero"><div class="tip-hero-copy">${wikiVisual(t)}<div><p class="eyebrow">CONFIDENCE WIKI</p><h2>${escapeHtml(t.title)}</h2><p>${escapeHtml(t.intro)}</p></div></div></div><div class="tip-columns"><div><h3>DO THIS</h3><ol>${t.steps.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ol></div><div><h3>SAY THIS</h3>${t.say.map(x=>`<div class="say-chip">“${escapeHtml(x)}”</div>`).join('')}</div><div><h3>AVOID THIS</h3>${t.avoid.map(x=>`<div class="avoid-chip">${escapeHtml(x)}</div>`).join('')}</div></div>${activity}`;$("#wikiBack").onclick=()=>{d.classList.remove('wiki-modal-open');d.classList.add('hidden');document.body.classList.remove('wiki-modal-lock');renderTips()};const award=()=>{state.score=Math.min(100,(state.score||0)+.25);save();renderProgress();checkAchievements()};if(a.type==='choice')$$('.wiki-option').forEach(b=>b.onclick=()=>{const ok=+b.dataset.choice===a.correct;$$('.wiki-option').forEach(x=>x.disabled=true);b.classList.add(ok?'correct':'wrong');$("#wikiFeedback").innerHTML=`<strong>${ok?'✨ Strong choice.':'Try the stronger move.'}</strong><p>${escapeHtml(a.feedback)}</p>`;$("#wikiFeedback").classList.remove('hidden');award();sound(ok?'success':'click')});if(a.type==='multi')$("#checkWiki").onclick=()=>{const chosen=$$('.wiki-checks input:checked').map(x=>+x.dataset.check).sort().join(','),correct=a.correct.slice().sort().join(',');$("#wikiFeedback").innerHTML=`<strong>${chosen===correct?'✨ You got the core pieces.':'Almost — look for the limit + next action + genuine alternative.'}</strong><p>${escapeHtml(a.feedback)}</p>`;$("#wikiFeedback").classList.remove('hidden');award()};if(a.type==='order'){$$('.ladder-step').forEach(b=>b.onclick=()=>{const next=+b.dataset.step,picked=$$('.ladder-step.picked').length;if(next===picked){b.classList.add('picked');if(picked+1===a.options.length){$("#wikiFeedback").innerHTML=`<strong>✨ Conversation built.</strong><p>${escapeHtml(a.feedback)}</p>`;$("#wikiFeedback").classList.remove('hidden');award()}}else toast('Try the steps in order: 1, 2, 3…')})}if(a.type==='breath')$("#startBreath").onclick=()=>{let n=20,e=$("#breathOrb");e.textContent=n;const ti=setInterval(()=>{n--;e.textContent=n;if(n<=0){clearInterval(ti);e.textContent='Done ✨';$("#wikiFeedback").innerHTML=`<strong>Reset complete.</strong><p>${escapeHtml(a.feedback)}</p>`;$("#wikiFeedback").classList.remove('hidden');award()}},1000)};if(a.type==='countdown')$("#startWikiTimer").onclick=()=>{let n=3,e=$("#wikiTimer");e.textContent=n;const ti=setInterval(()=>{n--;e.textContent=n;if(n<=0){clearInterval(ti);e.textContent='GO!';$("#wikiFeedback").innerHTML=`<strong>Now do it.</strong><p>${escapeHtml(a.feedback)}</p>`;$("#wikiFeedback").classList.remove('hidden');award()}},1000)};if(a.type==='pause')$("#startPause").onclick=()=>{let n=10,e=$("#pauseCount");e.textContent=n;const ti=setInterval(()=>{n--;e.textContent=n;if(n<=0){clearInterval(ti);e.textContent='Choose';$("#pausePrompt").classList.remove('hidden');award()}},1000)};if(a.type==='micro')$("#microDone").onclick=()=>{$("#wikiFeedback").innerHTML='<strong>🌷 Good.</strong><p>You let the compliment land.</p>';$("#wikiFeedback").classList.remove('hidden');award()};if($("#saveTipPractice"))$("#saveTipPractice").onclick=()=>{const fields=$$('.wiki-builder-field'),text=fields.length?fields.map(x=>x.value.trim()).filter(Boolean).join('\n'):($("#tipPractice")?.value||'').trim();if(!text){toast('Write a little first ✍️');return}state.journal.push({date:todayKey(),prompt:`Confidence Wiki · ${t.title}`,text});state.score=Math.min(100,(state.score||0)+.5);save();toast('Practice saved to your Journal Pad. ✨');renderProgress();checkAchievements()};$$('.wiki-ratings input').forEach(i=>i.oninput=()=>i.nextElementSibling.textContent=i.value+'/5')}
const copyEmailBtn=$("#copyEmail");if(copyEmailBtn)copyEmailBtn.onclick=async()=>{try{await navigator.clipboard.writeText('kikebabatundelawal@gmail.com');toast('Email copied ✉️')}catch{toast('kikebabatundelawal@gmail.com')}};
if(!state.unlockedAchievements.length){state.unlockedAchievements=getMilestones().filter(x=>x[2]).map(x=>x[0]);save()} checkAchievements(); if(!state.profile)$("#onboarding").classList.remove('hidden');renderHome();renderScenarios();renderDaily();renderSpeech();renderTracker();renderProgress();renderEvidence();renderProfile();renderJournal();renderTips();


const sendEmailBtn=document.querySelector('.contact-buttons a[href*="mail.google.com"]');if(sendEmailBtn){sendEmailBtn.href='mailto:kikebabatundelawal@gmail.com?subject='+encodeURIComponent('Ascendia feedback');sendEmailBtn.removeAttribute('target');sendEmailBtn.removeAttribute('rel');}
